-- Migration: 20261001000000_seed_notebook_slides_and_videos.sql
-- Seed 54 Notebook Slides (27) and Videos (27) across all 9 disciplines

-- 1. Inserir em Drive_Materials
ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name,
  mime_type = EXCLUDED.mime_type,
  web_view_link = EXCLUDED.web_view_link,
  folder_id = EXCLUDED.folder_id,
  file_size_bytes = EXCLUDED.file_size_bytes;

-- Fallback para drive_materials lowercase
DO $$
BEGIN
  IF EXISTS (SELECT FROM pg_tables WHERE schemaname = 'public' AND tablename = 'drive_materials') THEN
    ON CONFLICT (id) DO UPDATE SET
      name = EXCLUDED.name,
      mime_type = EXCLUDED.mime_type,
      web_view_link = EXCLUDED.web_view_link,
      folder_id = EXCLUDED.folder_id,
      file_size_bytes = EXCLUDED.file_size_bytes;
  END IF;
END $$;

-- 2. Inserir em materiais
ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
  google_drive_url = EXCLUDED.google_drive_url,
  file_url = EXCLUDED.file_url;
